interface.signature:
interface ConfigState {
  marbleSlug: string;
  width: number;
  height: number;
  depth: number;
  finish: FinishType;
  calculatedWeight: number;
  calculatedPrice: number;
  _hasHydrated: boolean;
}

interface ConfigActions {
  setMarble: (slug: string) => void;
  setDimensions: (dims: Partial<{width: number; height: number; depth: number}>) => void;
  setFinish: (finish: FinishType) => void;
  resetConfiguration: () => void;
  recalculate: () => void;
}

interface MarbleConstants {
  density: number;        // kg/m³
  basePricePerCm3: number; // cents
}
type MarbleDataMap = Record<string, MarbleConstants>;
